import { fileTypeFromBuffer } from 'file-type';

export async function inferImageContentType(file) {
  // Prefer browser-provided MIME type if available
  const t = (file?.type || '').toLowerCase().trim();
  if (t.startsWith('image/')) return t;

  // Fallback: validate file magic bytes
  if (file && file.slice) {
    const buffer = await file.slice(0, 4100).arrayBuffer();
    const type = await fileTypeFromBuffer(buffer);
    if (type && type.mime.startsWith('image/')) {
      return type.mime;
    }
  }

  // Last resort: extension-based guess (still insecure, but better than nothing)
  const n = (file?.name || '').toLowerCase();
  if (n.endsWith('.jpg') || n.endsWith('.jpeg')) return 'image/jpeg';
  if (n.endsWith('.png')) return 'image/png';
  if (n.endsWith('.webp')) return 'image/webp';
  if (n.endsWith('.gif')) return 'image/gif';
  if (n.endsWith('.heic') || n.endsWith('.heif')) return 'image/heic';
  return '';
}

