export async function notifyUsersOneAtATime(userIds, { title, message, type = 'info', link = null }, client = null) {
  const q = client ? client.query.bind(client) : query;
  const t = clipTitle(title);
  const BATCH_SIZE = 500;
  for (let i = 0; i < userIds.length; i += BATCH_SIZE) {
    const batch = userIds.slice(i, i + BATCH_SIZE);
    const values = [];
    const params = [];
    let paramIndex = 1;
    for (const userId of batch) {
      values.push(`($${paramIndex}, $${paramIndex + 1}, $${paramIndex + 2}, $${paramIndex + 3}, $${paramIndex + 4})`);
      params.push(userId, t, message, type, link);
      paramIndex += 5;
    }
    await q(
      `INSERT INTO notifications (user_id, title, message, type, link) VALUES ${values.join(', ')}`,
      params,
    );
  }
}

